function runtimeFailureError(code: DevRuntimeErrorCode, failure: RuntimeFailure, fallback: string, status?: number): DevRuntimeError {
	const message = failure.message ? (failure.diagnostic ? `${failure.diagnostic}: ${failure.message}` : failure.message) : fallback;
	const extra: { diagnostic?: string; reportToken?: string; details?: unknown; status?: number } = { details: failure.details };
	if (failure.diagnostic) extra.diagnostic = failure.diagnostic;
	if (failure.report_token) extra.reportToken = failure.report_token;
	if (status !== undefined) extra.status = status;
	return new DevRuntimeError(code, message, extra);
}
